class stringx
{
    char* chars;
    void* my_buf;

public:
    stringx();
};

template<class T>
class vector
{
    T* begin;
    T* end;
    T* capacity;

public:
    vector() : begin(0), end(0), capacity(0) {}
};

class hw_texture;

template<class T>
class refptr
{
    T* pointer;
};

class vertex_context
{
    unsigned int data;
};

class color32
{
    unsigned char value[4];

public:
    color32(unsigned char r, unsigned char g, unsigned char b, unsigned char a)
    {
        value[0] = r;
        value[1] = g;
        value[2] = b;
        value[3] = a;
    }
};

class anim_texture
{
    stringx filename;
    vector<refptr<hw_texture> > frame_list;
    vector<vertex_context> vc_list;
    unsigned int tex_flags;
    unsigned int blend_mode;
    float blend_amount;
    color32 diffuse_color;

public:
    anim_texture() : tex_flags(0), diffuse_color(255, 255, 255, 255) {}
};

class chunk_file;

class material
{
public:
    material(chunk_file& io, const stringx& texture_dir,
             unsigned int additional_mat_flags,
             unsigned int additional_tex_flags);

    void set_defaults();
    void build_hash_name();

    stringx material_name;
    stringx texture_filename[4];
    anim_texture diffuse_map[4];
    float u_anim;
    float v_anim;
    float det_u_scale;
    float det_v_scale;
    float det_range;
    float det_alpha_clamp;
    unsigned int mat_flags;
};

void serial_in(chunk_file& io, material* m, const stringx& texture_dir,
               unsigned int additional_mat_flags,
               unsigned int additional_tex_flags);

__asm__(".equ __7stringx, 0x0034D3E0");
__asm__(".equ set_defaults__8material, 0x003394C0");
__asm__(".equ serial_in__FR10chunk_fileP8materialRC7stringxUiUi, 0x00338990");
__asm__(".equ build_hash_name__8material, 0x00339538");

material::material(chunk_file& io, const stringx& texture_dir,
                   unsigned int additional_mat_flags,
                   unsigned int additional_tex_flags)
{
    set_defaults();
    serial_in(io, this, texture_dir, additional_mat_flags, additional_tex_flags);
    build_hash_name();
}
